    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] start = new int[n], finish = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); start[i] = (int) in.nval;
            in.nextToken(); finish[i] = (int) in.nval;
        }
        int[] courts = assignCourts(start, finish);
        int k = 0;
        for (int c : courts) k = Math.max(k, c);
        StringBuilder sb = new StringBuilder();
        sb.append(k).append("\n");
        for (int i = 0; i < courts.length; i++) sb.append(courts[i]).append(i + 1 < courts.length ? " " : "\n");
